'use client'
import { fetchIngredientPricing } from "../../util/actions";
import IngredientDetails from "../../types/models/IngredientDetails";
import SearchInput from "@/app/components/Elements/SearchInput";
import { useEffect, useState } from "react";
import { useDispatch } from "react-redux";
import { setManagerSearchTerm } from "@/redux/features/search/searchSlice";

const getAllIngredients = async () => {
  const response = await fetchIngredientPricing(1);
  return response;
}

export default function MarketContainer() {
    const [ingredients, setIngredients] = useState<IngredientDetails[]>([]);
    const [searchTerm, setSearchTerm] = useState<string>("");
    const dispatch = useDispatch();
    useEffect(() => {
        const fetchIngredients = async () => {
            const ing = await getAllIngredients();
            setIngredients(ing);
        };
        fetchIngredients();
    }, []);

    const handleSearch = (query: string) => {
        setSearchTerm(query);

        dispatch(setManagerSearchTerm(query));
        
    }

    return (
        <div className="flex flex-col items-center">
            <div class="flex items-center justify-between mb-4 w-full">
    <h1 class="text-3xl font-bold" style="font-family: 'Times New Roman';">Market</h1>
    <div class="ml-4">
        <input 
            type="text"
            placeholder="Search..."
            class="border px-3 py-2 rounded-md"
            onChange={handleSearchChange}
        />
        <p class="text-sm text-red-500" style="display: {searchTerm ? 'none' : 'block'};">Please enter a search term.</p>
    </div>
</div>
            {/* Additional content can be added below this level */}
            <div className="mt-4">
                {/* Placeholder for more content */}
                {ingredients.length > 0 ? (
                    <ul>
                        {ingredients.map((ingredient) => (
                            <li key={ingredient.ingredientId}>{ingredient.ingredientName}</li>
                        ))}
                    </ul>
                ) : (
                    <p>No ingredients found.</p>
                )}
            </div>
        </div>
    );
}
